B.aFv=new A.b(B.aUr,["\ubd88 \uc880 \ub354 \ucb10\uace0 \uac00.","\ubcc4 \ud558\ub098 \ub5b4\ub2e4!","\ub0b4\uc77c\uc740 \ubb58 \ub053\uc774\ub098.","\ud654\ubd84\uc5d0 \uc0c8 \uc78e \ub0ac\ub354\ub77c.","\ubb3c \uc8fc\ub294 \uac70 \uae4c\uba39\uc9c0 \ub9c8.","\uc7a0\uae50 \uc549\uc558\ub2e4 \uac08\uac8c.","\uac00\ub85c\ub4f1 \ubc11\uc774 \uc81c\uc77c \ub530\ub73b\ud574.","\ubc24\uc774 \ub35c \ubb34\uc12d\ub124.","\ud48d\uacbd \uc18c\ub9ac \ub4e4\ub824?","\ubc14\ub78c \ubc14\ub00c\uc5c8\ub2e4.","\ubd88\ube5b \uc904 \uc544\ub798\ub85c \ubaa8\uc5ec, \ub2e4\ub4e4.","\ubc24\uc774 \uc794\uce6b\ub0a0 \uac19\ub124.","\ub204\uac00 \uadf8\ub838\ub294\uc9c0 \uc54c\uaca0\ub2e4.","\uc5ec\uae30 \uc11c\uba74 \ub9c8\uc74c\uc774 \uc880 \uac00\ub77c\uc549\uc544.","\uc78a\uc9c0 \ub9d0\uc790\ub294 \uac70\uc9c0, \uc774\uac70.","\ub9dd\uce58 \uc18c\ub9ac \uc88b\uc9c0 \uc54a\uc544?","\ucca0\ud310 \ud55c \uc7a5 \ub354 \ub098\uc624\uaca0\uc5b4.","\ud759\uc774 \ub2e4\uc2dc \ubd80\ub4dc\ub7ec\uc6cc\uc84c\uc5b4.","\uac10\uc790 \uc2f9 \ub0ac\ub2e4! \uad6d\uc5d0 \ub123\uc5b4\uc57c\uc9c0.","\ube57\ubb3c\uc774 \ub9d1\uac8c \uac78\ub7ec\uc9c0\ub124. \uc721\uc218 \ub0bc \ub9cc\ud558\uaca0\uc5b4.","\ubb3c \uac71\uc815\uc740 \ub35c\uc5c8\ub2e4.","\uc0c1\uc790\ub9c8\ub2e4 \uc774\ub984\ud45c \ubd99\uc5ec \ub1a8\uc5b4.","\ucc3d\uace0\uac00 \ub4e0\ub4e0\ud558\ub124.","\uc5f0\ub8cc\ub9cc \uc788\uc73c\uba74 \ubc24\uc0c8 \ub3cc\uc544\uac00.","\uc804\uad6c \ub2e4\uc2dc \ucf1c\uc84c\ub2e4!","\ub2e4\uce5c \ub370 \uc5c6\uc9c0?","\ubd95\ub300\ub294 \ub109\ub109\ud574.","\uc7a1\uc74c \uc18d\uc5d0 \ub204\uac00 \ubd80\ub974\ub294 \uac83 \uac19\uc544.","\uc624\ub298\ub3c4 \uc2e0\ud638 \uae30\ub2e4\ub824 \ubcf4\uc790.","\ubd88 \uaebc\uc9c0\uc9c0 \uc54a\uac8c \ub0b4\uac00 \uc9c0\ud0ac\uac8c.","\uba40\ub9ac\uae4c\uc9c0 \ube5b\uc774 \ub2ff\ub124.","\uc774 \uace0\ucca0 \ub354\ubbf8\uac00 \ub2e4 \ubcf4\ubb3c\uc774\uc57c.","\uc4f8 \ub9cc\ud55c \uac70 \ub610 \ub098\uc654\ub2e4!"],t.w)
